// Modelo de juguete de la cola: A tiene el lock hasta el segundo 6,
// B (ACCESS EXCLUSIVE) llega en 1 y C (un select) llega en cLlega.
function simular({ cLlega, lockTimeout }) {
  const aSale = 6.0, bLlega = 1.0, bDur = 0.0001;
  const bEmpieza = Math.max(bLlega, aSale);
  let bAborta = null;
  if (lockTimeout !== null && bLlega + lockTimeout < aSale) bAborta = bLlega + lockTimeout;
  // C queda detrás de B mientras B esté esperando
  const cEmpieza = bAborta !== null ? Math.max(cLlega, bAborta) : Math.max(cLlega, bEmpieza + bDur);
  return {
    b: bAborta !== null ? `cancelada tras ${(bAborta - bLlega).toFixed(1)} s` : `espera ${(bEmpieza - bLlega).toFixed(1)} s`,
    c: `espera ${(cEmpieza - cLlega).toFixed(1)} s`
  };
}
console.log('sin lock_timeout    ', simular({ cLlega: 2.0, lockTimeout: null }));
console.log('lock_timeout de 1 s ', simular({ cLlega: 1.5, lockTimeout: 1 }));
console.log('lock_timeout de 10 s', simular({ cLlega: 2.0, lockTimeout: 10 }));

