-- migración 1: expandir (instantánea)
alter table bultos add column peso_kg numeric(6,2);

create function sincronizar_peso() returns trigger language plpgsql as $$
begin
  if tg_op = 'INSERT' then
    new.peso_kg := coalesce(new.peso_kg, new.peso);
    new.peso    := coalesce(new.peso, new.peso_kg);
  elsif new.peso_kg is distinct from old.peso_kg then
    new.peso := new.peso_kg;
  elsif new.peso is distinct from old.peso then
    new.peso_kg := new.peso;
  end if;
  return new;
end $$;

create trigger bultos_sincronizar_peso before insert or update on bultos
  for each row execute function sincronizar_peso();

